from pathlib import Path
import hashlib
import csv
import time


# ============================================================
# CONFIGURATION
# ============================================================

DATA_DIR = Path(r"C:\Users\sakkari\Code\hlc-bias-model\data")

# Manifest generated by inventory.py
MANIFEST_FILE = Path("metadata") / "manifest.csv"

# Read 8 MB at a time
CHUNK_SIZE = 8 * 1024 * 1024


# ============================================================
# SHA-256 FUNCTION
# ============================================================

def calculate_sha256(file_path):

    sha256 = hashlib.sha256()

    total_bytes = file_path.stat().st_size
    processed_bytes = 0

    start_time = time.time()

    with file_path.open("rb") as f:

        while True:

            chunk = f.read(CHUNK_SIZE)

            if not chunk:
                break

            sha256.update(chunk)

            processed_bytes += len(chunk)

            elapsed = time.time() - start_time

            if elapsed > 0:
                speed_mb_s = (
                    processed_bytes /
                    (1024 ** 2) /
                    elapsed
                )
            else:
                speed_mb_s = 0

            percent = (
                processed_bytes /
                total_bytes *
                100
            )

            print(
                f"\r"
                f"{percent:6.2f}% "
                f"({speed_mb_s:6.1f} MB/s)",
                end="",
                flush=True
            )

    print()

    return sha256.hexdigest()


# ============================================================
# CHECK DATA DIRECTORY
# ============================================================

if not DATA_DIR.exists():

    raise FileNotFoundError(
        f"Dataset directory does not exist:\n{DATA_DIR}"
    )


# ============================================================
# LOAD MANIFEST
# ============================================================

if not MANIFEST_FILE.exists():

    raise FileNotFoundError(
        f"Manifest does not exist:\n"
        f"{MANIFEST_FILE}\n\n"
        "Run inventory.py first."
    )


with MANIFEST_FILE.open(
    "r",
    encoding="utf-8",
    newline=""
) as f:

    manifest = list(
        csv.DictReader(f)
    )


# ============================================================
# CHECK MANIFEST
# ============================================================

if not manifest:

    raise ValueError(
        "The manifest is empty."
    )


# ============================================================
# CALCULATE CHECKSUMS
# ============================================================

print()
print("=" * 70)
print("SHA-256 CHECKSUM GENERATION")
print("=" * 70)

print()
print(
    "The manifest will be updated with a SHA-256 checksum "
    "for every file."
)

print()


for index, record in enumerate(manifest, start=1):

    relative_path = record["relative_path"]

    file_path = DATA_DIR / relative_path

    if not file_path.exists():

        raise FileNotFoundError(
            f"\nFile listed in manifest does not exist:\n"
            f"{file_path}"
        )

    if not file_path.is_file():

        raise ValueError(
            f"\nManifest path is not a file:\n"
            f"{file_path}"
        )

    print()
    print("-" * 70)
    print(
        f"File {index} of {len(manifest)}"
    )
    print(
        f"Configuration: {record['configuration_id']}"
    )
    print(
        f"Component:     {record['component']}"
    )
    print(
        f"File:          {record['file_name']}"
    )
    print(
        f"Size:          {record['size_gb']} GB"
    )
    print()

    print("Calculating SHA-256...")

    sha256 = calculate_sha256(file_path)

    print(
        f"SHA-256: {sha256}"
    )

    record["sha256"] = sha256


# ============================================================
# WRITE UPDATED MANIFEST
# ============================================================

fieldnames = [
    "configuration_id",
    "configuration_name",
    "building_system",
    "insulation_configuration",
    "component",
    "file_name",
    "relative_path",
    "size_bytes",
    "size_gb",
    "column_count",
    "sha256",
]


with MANIFEST_FILE.open(
    "w",
    encoding="utf-8",
    newline=""
) as f:

    writer = csv.DictWriter(
        f,
        fieldnames=fieldnames
    )

    writer.writeheader()
    writer.writerows(manifest)


# ============================================================
# SUMMARY
# ============================================================

print()
print("=" * 70)
print("CHECKSUM GENERATION COMPLETE")
print("=" * 70)

print()
print(
    f"Files hashed: {len(manifest)}"
)

print()
print("Updated manifest:")
print(
    f"  {MANIFEST_FILE.resolve()}"
)

print()
print(
    "The SHA-256 checksums are now stored directly "
    "in manifest.csv."
)

print()